mapper.insert:
INSERT INTO seat_current_room ( pblib_id, stdg_cd, rdrm_id, pblib_nm, lclgv_nm, rdrm_nm, now_vstr_cnt, tseat_cnt, use_seat_cnt, rsvt_seat_cnt, rmnd_seat_cnt, updated_at, name_norm, region_norm) SELECT r.stdg_cd, r.pblib_id, r.rdrm_id,
/* 원본 JSON에서 문자열 값 추출, JSON_EXTRACT -> JSON String("...") -> JSON_UNQUOTE으로 따옴표 제거 */ JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.pblibNm')) AS pblib_nm, JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.lclgvNm')) AS lclgv_nm, JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.rdrmNm')) AS rdrm_nm,
/* 숫자: 빈문자열("") → NULL 처리 후 캐스팅, NOT NULL이면 0으로 보강 */ COALESCE(CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.nowVstrCnt')), '') AS UNSIGNED), 0) AS nowVstrCnt, COALESCE(CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.tseatCnt')), '') AS UNSIGNED), 0) AS tseatCnt, COALESCE(CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.useSeatCnt')), '') AS UNSIGNED), 0) AS useSeatCnt, COALESCE(CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.rsvtSeatCnt')), '') AS UNSIGNED), 0) AS rsvtSeatCnt, COALESCE(CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.rmndSeatCnt')), '') AS UNSIGNED), 0) AS rmndSeatCnt,
/* ymdhms 형식 문자열을 찾아서 DATETIME으로 변환 */ STR_TO_DATE(r.tot_dt, '%Y%m%d%H%i%s') AS updatedAt,
/* 검색용 정규화 칼럼(공백제거 + 소문자) */ COALESCE(LOWER(REPLACE(JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.pblibNm')), ' ', '')), '') AS nameNorm, COALESCE(LOWER(REPLACE(JSON_UNQUOTE(JSON_EXTRACT(r.payload, '$.lclgvNm')), ' ', '')), '') AS regionNorm FROM seat_raw_item r JOIN ( SELECT stdg_cd, pblib_id, rdrm_id, MAX(tot_dt) AS max_tot_dt FROM seat_raw_item WHERE stdg_cd = #{key.stdgCd} AND pblib_id = #{key.pblibId} AND rdrm_id = #{key.rdrmId} GROUP BY pblib_id, rdrm_id) t ON t.stdg_cd = r.stdg_cd AND t.pblib_id = r.pblib_id AND t.rdrm_id = r.rdrm_id AND t.max_tot_dt = r.tot_dt WHERE JSON_VALID(r.payload) ON DUPLICATE KEY UPDATE pblib_nm = VALUES(pblib_nm), lclgv_nm = VALUES(lclgv_nm), rdrm_nm = VALUES(rdrm_nm), now_vstr_cnt = VALUES(now_vstr_cnt), tseat_cnt = VALUES(tseat_cnt), use_seat_cnt = VALUES(use_seat_cnt), rsvt_seat_cnt = VALUES(rsvt_seat_cnt), rmnd_seat_cnt = VALUES(rmnd_seat_cnt), updated_at = VALUES(updated_at), name_norm = VALUES(name_norm), region_norm = VALUES(region_norm);
